CREATE OR REPLACE FUNCTION public.sync_invited_role_projection() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE legacy public.app_role;BEGIN IF NEW.status='accepted' AND OLD.status IS DISTINCT FROM NEW.status THEN SELECT enumlabel::public.app_role INTO legacy FROM pg_enum WHERE enumtypid='public.app_role'::regtype AND enumlabel=CASE WHEN NEW.role='investor_viewer' THEN 'investor' ELSE NEW.role END;IF legacy IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role,is_active) VALUES(NEW.accepted_by,legacy,true) ON CONFLICT(user_id,role) DO UPDATE SET is_active=true;END IF;END IF;RETURN NEW;END $$;
CREATE OR REPLACE TRIGGER invitation_role_projection AFTER UPDATE ON public.staff_invitations FOR EACH ROW EXECUTE FUNCTION public.sync_invited_role_projection();REVOKE ALL ON FUNCTION public.sync_invited_role_projection() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.validate_permission_boundary() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.role='sales_agent' AND ((NEW.capability IN('opportunities.write','contracts.draft','customers.contacts') AND NEW.level NOT IN('none','own')) OR (NEW.capability='opportunities.assign' AND NEW.level<>'none') OR (NEW.capability LIKE 'finance.%' AND NEW.level<>'none')) THEN RAISE EXCEPTION 'المبيعات تعدل فرصها ومسوداتها وتكشف بيانات عملائها فقط ولا تصل للمال أو إعادة التوزيع';END IF;IF NEW.role='manager' AND NEW.capability='customers.contacts' AND NEW.level<>'none' THEN RAISE EXCEPTION 'بيانات التواصل الكاملة ليست متاحة للمدير';END IF;RETURN NEW;END $$;
CREATE OR REPLACE TRIGGER permission_boundary_guard BEFORE INSERT OR UPDATE ON public.role_permissions FOR EACH ROW EXECUTE FUNCTION public.validate_permission_boundary();
CREATE OR REPLACE FUNCTION public.permission_safety_checks() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_permission('security.roles','edit') THEN RAISE EXCEPTION 'فحص الأمان للأدمن';END IF;RETURN jsonb_build_object('own_not_global_view',NOT public.permission_levels_allow('own','view'),'own_not_global_edit',NOT public.permission_levels_allow('own','edit'),'approve_not_edit',NOT public.permission_levels_allow('approve','edit'),'unknown_denied',NOT public.permission_levels_allow('unknown','edit'),'sales_finance_denied',NOT EXISTS(SELECT 1 FROM public.role_permissions WHERE role='sales_agent' AND capability LIKE 'finance.%' AND level<>'none'),'sales_contacts_owned',EXISTS(SELECT 1 FROM public.role_permissions WHERE role='sales_agent' AND capability='customers.contacts' AND level='own'),'no_direct_opportunity_writes',NOT has_table_privilege('authenticated','public.opportunities','UPDATE'),'internal_tables_locked',NOT has_table_privilege('anon','public.party_code_counter','SELECT') AND NOT has_table_privilege('authenticated','public.assignment_state','UPDATE'),'invitation_projection_exists',EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='invitation_role_projection'));END $$;
REVOKE ALL ON FUNCTION public.permission_safety_checks() FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.permission_safety_checks() TO authenticated;
SELECT to_regprocedure('public.permission_safety_checks()') IS NOT NULL AS safety_checks_ready;